#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
layout(color) uniform half4 amzp_color5;
uniform float amzp_stop1;
uniform float amzp_stop2;
uniform float amzp_stop3;
uniform float amzp_stop4;
uniform float amzp_stop5;
uniform float amzp_lumMode;
uniform float amzp_gradGamma;
uniform float amzp_gradContrast;
uniform float amzp_gradBrightness;
uniform float amzp_gradInvert;
uniform float amzp_gradReverse;
uniform float amzp_mapStrength;
uniform float amzp_blendMode;
uniform float amzp_preserveLum;
uniform float amzp_preserveSat;
uniform float amzp_preserveHue;
uniform float amzp_hueShift;
uniform float amzp_satAdjust;
uniform float amzp_lumAdjust;
uniform float amzp_shadowsOnly;
uniform float amzp_midtonesOnly;
uniform float amzp_highlightsOnly;
uniform float amzp_duotoneMode;
layout(color) uniform half4 amzp_duoShadow;
layout(color) uniform half4 amzp_duoHighlight;
uniform float amzp_globalMix;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float getLum(float3 c, float m) {
        if (m < 1.5) return dot(c, float3(0.2126, 0.7152, 0.0722));
        if (m < 2.5) return max(c.r, max(c.g, c.b));
        if (m < 3.5) return (c.r + c.g + c.b) / 3.0;
        if (m < 4.5) return pow(dot(pow(max(c, 0.0), float3(2.2)), float3(0.2126, 0.7152, 0.0722)), 1.0 / 2.2);
        if (m < 5.5) return c.r;
        if (m < 6.5) return c.g;
        if (m < 7.5) return c.b;
        return (max(c.r, max(c.g, c.b)) + min(c.r, min(c.g, c.b))) * 0.5;
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b)), mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5, d = mx - mn, s = 0.0, h = 0.0;
        if (d > 0.00001) {
            s = l > 0.5 ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
            else if (mx == c.g) h = (c.b - c.r) / d + 2.0;
            else h = (c.r - c.g) / d + 4.0;
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = c.z < 0.5 ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p, q, c.x + 1.0 / 3.0), h2r(p, q, c.x), h2r(p, q, c.x - 1.0 / 3.0));
    }
    float3 seg(float3 a, float3 b, float t, float s0, float s1) { float f = clamp((t - s0) / max(s1 - s0, 0.00001), 0.0, 1.0); return mix(a, b, f * f * (3.0 - 2.0 * f)); }
    float3 grad5(float t, float3 c1, float3 c2, float3 c3, float3 c4, float3 c5) {
        if (t <= amzp_stop1) return c1;
        if (t >= amzp_stop5) return c5;
        if (t < amzp_stop2) return seg(c1, c2, t, amzp_stop1, amzp_stop2);
        if (t < amzp_stop3) return seg(c2, c3, t, amzp_stop2, amzp_stop3);
        if (t < amzp_stop4) return seg(c3, c4, t, amzp_stop3, amzp_stop4);
        return seg(c4, c5, t, amzp_stop4, amzp_stop5);
    }
    float ov(float b, float m) { return b < 0.5 ? 2.0 * b * m : 1.0 - 2.0 * (1.0 - b) * (1.0 - m); }
    float sl(float b, float m) { return m < 0.5 ? 2.0 * b * m + b * b * (1.0 - 2.0 * m) : 2.0 * b * (1.0 - m) + sqrt(max(b, 0.0)) * (2.0 * m - 1.0); }
    float3 blendC(float3 b, float3 m, int mode) {
        if (mode == 0) return m;
        if (mode == 1) return b * m;
        if (mode == 2) return 1.0 - (1.0 - b) * (1.0 - m);
        if (mode == 3) return float3(ov(b.r, m.r), ov(b.g, m.g), ov(b.b, m.b));
        if (mode == 4) return float3(sl(b.r, m.r), sl(b.g, m.g), sl(b.b, m.b));
        float3 mh = rgb2hsl(m), bh = rgb2hsl(b);
        if (mode == 5) return hsl2rgb(float3(mh.x, mh.y, bh.z));
        return hsl2rgb(float3(bh.x, bh.y, mh.z));
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float4 src = orig;
        float3 rgb = src.a > 0.0001 ? max(src.rgb / src.a, 0.0) : float3(0.0);
        float t = getLum(rgb, float(int(amzp_lumMode)) + 1.0);
        if (abs(amzp_gradGamma - 1.0) > 0.00001) t = pow(max(t, 0.0), 1.0 / max(amzp_gradGamma, 0.00001));
        if (abs(amzp_gradContrast) > 0.5) t = clamp((t - 0.5) * (1.0 + amzp_gradContrast / 100.0) + 0.5, 0.0, 1.0);
        if (abs(amzp_gradBrightness) > 0.5) t = clamp(t + amzp_gradBrightness / 100.0 * 0.3, 0.0, 1.0);
        if ((amzp_gradInvert>0.5)) t = 1.0 - t;
        float3 c1 = amzp_color1.rgb, c2 = amzp_color2.rgb, c3 = amzp_color3.rgb, c4 = amzp_color4.rgb, c5 = amzp_color5.rgb;
        if ((amzp_gradReverse>0.5)) { float3 tp = c1; c1 = c5; c5 = tp; tp = c2; c2 = c4; c4 = tp; }
        if ((amzp_duotoneMode>0.5)) { c1 = amzp_duoShadow.rgb; c5 = amzp_duoHighlight.rgb; c2 = mix(c1, c5, 0.25); c3 = mix(c1, c5, 0.5); c4 = mix(c1, c5, 0.75); }
        float3 mp = grad5(t, c1, c2, c3, c4, c5);
        float shM = 1.0 - smoothstep(0.0, 0.4, t), hiM = smoothstep(0.6, 1.0, t), miM = max(1.0 - shM - hiM, 0.0);
        mp = mix(rgb, mp, shM * amzp_shadowsOnly + miM * amzp_midtonesOnly + hiM * amzp_highlightsOnly);
        mp = mix(rgb, mp, amzp_mapStrength);
        float3 bl = blendC(rgb, mp, int(amzp_blendMode));
        if (amzp_preserveHue > 0.00001) { float3 o = rgb2hsl(rgb), b = rgb2hsl(max(bl, 0.0)); b.x = mix(b.x, o.x, amzp_preserveHue); bl = hsl2rgb(b); }
        if (amzp_preserveSat > 0.00001) { float3 o = rgb2hsl(rgb), b = rgb2hsl(max(bl, 0.0)); b.y = mix(b.y, o.y, amzp_preserveSat); bl = hsl2rgb(b); }
        if (amzp_preserveLum > 0.00001) { float ol = dot(rgb, float3(0.2126, 0.7152, 0.0722)), nl = dot(bl, float3(0.2126, 0.7152, 0.0722)); if (nl > 0.00001) bl *= mix(1.0, ol / nl, amzp_preserveLum); }
        if (abs(amzp_hueShift) > 0.5 || abs(amzp_satAdjust) > 0.5 || abs(amzp_lumAdjust) > 0.5) {
            float3 h = rgb2hsl(max(bl, 0.0));
            h.x = fract(h.x + amzp_hueShift / 360.0);
            h.y = clamp(h.y * (1.0 + amzp_satAdjust / 100.0), 0.0, 1.0);
            h.z = clamp(h.z + amzp_lumAdjust / 100.0 * 0.3, 0.0, 1.0);
            bl = hsl2rgb(h);
        }
        float3 fin = clamp(mix(rgb, bl, amzp_globalMix), 0.0, 1.0);
        float4 R = float4(fin * src.a, src.a);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
